// Writes .github/workflows/promo-manual.yml: a manual "post this tool now" workflow with one dropdown per category listing every tool by name.
// Run `node .github/scripts/generate-promo-manual.mjs` after the tool catalogue changes (tests/promo-manual.test.mjs fails if it is out of date).
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import { CATALOG } from '../../cloudflare/src/promo-catalog.js';

export const CATS = [['pdf', 'PDF'], ['image', 'Image'], ['business', 'Business'], ['video', 'Video'], ['ai', 'AI'], ['education', 'Education']];
export const NONE = '(none)';
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
export const optionLabel = (t) => `${t.id} — ${t.ta && t.ta !== t.name ? t.ta + ' / ' : ''}${t.name}${t.paid ? ' (AI, paid)' : ''}`.slice(0, 120);
export const toolFromChoice = (v) => (!v || v.startsWith('(') ? '' : v.split(' ')[0]);

export function buildYaml(catalog = CATALOG) {
  const inputs = CATS.map(([cat, label]) => {
    const items = catalog.filter((t) => t.cat === cat);
    return `      tool_${cat}:
        description: '${label} tools (${items.length}) — pick one, or leave (none)'
        type: choice
        default: ${q(NONE)}
        options:
          - ${q(NONE)}
${items.map((t) => `          - ${q(optionLabel(t))}`).join('\n')}`;
  }).join('\n');
  const envs = CATS.map(([cat]) => `          T_${cat.toUpperCase()}: \${{ inputs.tool_${cat} }}`).join('\n');
  return `name: Promotion — post a chosen tool now (manual)

# GENERATED by .github/scripts/generate-promo-manual.mjs from the tool catalogue — do not edit by hand.
# Pick ONE tool in ONE of the category lists below (leave the others at "(none)") and press Run workflow:
# the Short is made and posted to YouTube + Facebook + Instagram right now (whatever is connected).
# If every list is "(none)" the brain chooses the tool, exactly like the daily run.
on:
  workflow_dispatch:
    inputs:
${inputs}
      privacy:
        description: 'YouTube only: public (normal) or private (test). Facebook / Instagram posts are always public.'
        type: choice
        options: [public, private]
        default: public
      story:
        description: 'Story template (auto = by date)'
        type: choice
        options: [auto, tip, reject, queue, beard]
        default: auto

concurrency:
  group: promo-youtube
  cancel-in-progress: false

jobs:
  short:
    runs-on: ubuntu-24.04
    timeout-minutes: 15
    steps:
      - name: Work out the chosen tool
        id: pick
        env:
${envs}
        run: |
          picked=""
          for v in "$T_PDF" "$T_IMAGE" "$T_BUSINESS" "$T_VIDEO" "$T_AI" "$T_EDUCATION"; do
            case "$v" in ""|"("*) ;; *) if [ -z "$picked" ]; then picked="\${v%% *}"; else echo "::warning::More than one tool chosen — using the first ($picked)"; fi;; esac
          done
          echo "tool=$picked" >> "$GITHUB_OUTPUT"
          echo "Chosen tool: \${picked:-(brain decides)}"

      - name: Checkout code
        uses: actions/checkout@v4

      - name: Set up Node
        uses: actions/setup-node@v4
        with:
          node-version: 22

      - name: Install ffmpeg, emoji font, Inter font and the free Tamil voice (edge-tts, gTTS)
        run: |
          sudo apt-get update -qq
          sudo apt-get install -y -qq ffmpeg fonts-noto-color-emoji
          npm i --no-save --no-package-lock @fontsource/inter@5 playwright-core@1
          python3 -m pip install --user --break-system-packages --quiet edge-tts gTTS
          echo "$HOME/.local/bin" >> "$GITHUB_PATH"

      - name: Make and post the Short
        env:
          CLOUDFLARE_API_TOKEN: \${{ secrets.CLOUDFLARE_API_TOKEN }}
          CLOUDFLARE_ACCOUNT_ID: \${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          GOOGLE_CLIENT_ID: \${{ secrets.GOOGLE_CLIENT_ID }}
          GOOGLE_CLIENT_SECRET: \${{ secrets.GOOGLE_CLIENT_SECRET }}
          TOOL: \${{ steps.pick.outputs.tool }}
          GEMINI_API_KEY: \${{ secrets.GEMINI_API_KEY }}
          META_TOKEN: \${{ secrets.META_TOKEN }}
          FB_PAGE_ID: \${{ secrets.FB_PAGE_ID }}
          IG_USER_ID: \${{ secrets.IG_USER_ID }}
          PRIVACY: \${{ inputs.privacy }}
          STORY: \${{ inputs.story }}
        run: node .github/scripts/promo-youtube.mjs

      - name: Keep the video
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: short
          path: |
            short.mp4
            social-captions.txt
          if-no-files-found: ignore
          retention-days: 7
`;
}
if (process.argv[1] === fileURLToPath(import.meta.url)) { fs.writeFileSync('.github/workflows/promo-manual.yml', buildYaml()); console.log('Wrote .github/workflows/promo-manual.yml'); }
